import{_ as r,C as s,o as a,c as n,a2 as t,E as h}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/story-settings-story.webp",i="/guide/media/story-settings-goal.webp",l="/guide/media/story-settings-prose.webp",b=JSON.parse('{"title":"Story settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/story-settings.md","filePath":"guide/story-settings.md","lastUpdated":1792171429000}'),g={name:"guide/story-settings.md"};function c(p,e,u,y,m,f){const o=s("Clip");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="story-settings" tabindex="-1">Story settings <a class="header-anchor" href="#story-settings" aria-label="Permalink to &quot;Story settings&quot;">​</a></h1><p>A story&#39;s settings say where the story lives, which of its files are read, what the Desk counts it toward, how its prose marks speech and thought, which words to watch, which names are not people, and which threads do which job on the plot grid. They travel with the story: they are kept in the story&#39;s own folder, in <code>suite/Story.json</code>, so a story synced to another computer brings them along. This page goes through every field and what it changes.</p><p><img src="'+d+'" alt="The story settings page of The Lamp at Ferrol on its Story section: the section list on the left with counts, and the rows Name, Folder under the library, Mark and Files" width="1130" height="682" loading="lazy"></p><h2 id="opening-the-settings" tabindex="-1">Opening the settings <a class="header-anchor" href="#opening-the-settings" aria-label="Permalink to &quot;Opening the settings&quot;">​</a></h2><p>With a story open, any of these:</p><ul><li>The story&#39;s <code>⋯</code> menu in the sidebar (hover the story&#39;s name): <strong>Story settings</strong>.</li><li>The breadcrumb: click the view&#39;s name after the story and pick <strong>Story settings</strong> at the bottom of the menu, or open the story&#39;s own menu in the breadcrumb.</li><li>The command palette (<code>Ctrl+K</code>, or <code>Cmd+K</code> on macOS): <strong>Story settings</strong>.</li><li><strong>Settings</strong>, then the story in the <strong>Story</strong> list on the left, <strong>Structure and goals</strong>, and <strong>Open the story&#39;s settings</strong>.</li></ul><p>The page replaces the view, beside the story, so what Leathercase read of it is at hand. <strong>Back to the story</strong> at the foot of the section list, or <code>Esc</code>, returns to the view you came from.</p><h2 id="how-the-page-works" tabindex="-1">How the page works <a class="header-anchor" href="#how-the-page-works" aria-label="Permalink to &quot;How the page works&quot;">​</a></h2><p>The page has seven sections, listed on the left under the story&#39;s name: <strong>Story</strong>, <strong>Goal</strong>, <strong>Prose</strong>, <strong>Words</strong>, <strong>Characters</strong>, <strong>Graph</strong> and <strong>Plot grid</strong>. Some show a figure beside their name: the number of files the story reads, the target, the story&#39;s language (<code>EN</code>), the number of word lists, the number of names that are not people, and how many of the grid&#39;s four jobs are set (<code>2/4</code>).</p><p>Each section has a title, the file it writes at the top right, and a lead paragraph. Every change is written at once, as on the app&#39;s own settings pages: a text field when you leave it or press <code>Enter</code>, a list or a button the moment you pick it. A change to the folder or the file patterns reads the story again.</p><p>A change the story cannot take is refused, with the reason in rose, and not written:</p><ul><li><strong>A story needs a name.</strong></li><li><strong>A story needs at least one pattern, such as **/*.md.</strong></li></ul><h2 id="story" tabindex="-1">Story <a class="header-anchor" href="#story" aria-label="Permalink to &quot;Story&quot;">​</a></h2><p>&quot;Where the story lives in the home and which of its files are read. A change here reads the folder again.&quot;</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>The story&#39;s name, as the sidebar, the Library and the title page show it. Renaming it leaves the folder and your files as they are.</td></tr><tr><td><strong>Folder under the library</strong></td><td>The folder, inside the home, that holds the story, such as <code>The Lamp at Ferrol</code>. Empty means the whole home is the story.</td></tr><tr><td><strong>Mark</strong></td><td>&quot;How the story looks in the sidebar and the Library&quot;: a row of icons and a row of colours to pick from; the story&#39;s mark in the sidebar changes as you pick.</td></tr><tr><td><strong>Files</strong></td><td>How many files match (<strong>42 files match</strong>), and how many the leave-out patterns take away (<strong>· 3 left out</strong>). <strong>Show</strong> opens the story&#39;s folder as a tree with a tick for each file; <strong>Hide</strong> folds it. <strong>How it is read</strong> opens the page that shows what Leathercase made of every file.</td></tr></tbody></table><h3 id="the-file-tree" tabindex="-1">The file tree <a class="header-anchor" href="#the-file-tree" aria-label="Permalink to &quot;The file tree&quot;">​</a></h3><p><strong>Show</strong> lists every file of the story&#39;s folder. A ticked file is read; an unticked one is not. Tick or untick a file (<strong>Read 01 The Night the Lamp Went Out.md</strong>) or a whole folder (<strong>Read the folder Act I - The Dark Lamp</strong>), and Leathercase turns your ticks into patterns for you. The count above reads <strong>38 of 42 files</strong>; <strong>Clear</strong> unticks everything (the story needs at least one file to save).</p><p>Beside each folder, a list says what it holds:</p><table tabindex="0"><thead><tr><th>Choice</th><th>Means</th></tr></thead><tbody><tr><td><strong>The story&#39;s prose</strong></td><td>Chapters and scenes. Only the prose makes scenes.</td></tr><tr><td><strong>Characters</strong>, <strong>Places</strong>, <strong>Items</strong>, <strong>Factions</strong>, <strong>Events</strong></td><td>Notes about the story&#39;s world, one kind each.</td></tr><tr><td><strong>Plans (outline, synopsis)</strong>, <strong>Records (chronology, style sheet)</strong>, <strong>Work notes (journal, feedback)</strong>, <strong>Research</strong>, <strong>Scraps (cut scenes)</strong></td><td>Notes that are part of the story but not its prose.</td></tr><tr><td>A kind of your own</td><td>Kinds you declared for the story.</td></tr><tr><td><strong>As its folder</strong>, <strong>By its name: …</strong>, <strong>Not said: …</strong></td><td>Nothing said here: the folder above decides, or the folder&#39;s name does (<code>Characters/</code> reads as characters), or the files wait unsorted until you say.</td></tr></tbody></table><p>A note with its own <code>type:</code> in its front matter keeps that type whatever its folder says. The whole of this is explained in <a href="/guide/guide/how-a-story-is-read">How a story is read</a> and <a href="/guide/guide/declare-a-story">Declaring a story</a>.</p>',20)),h(o,{name:"story-settings-file-tree",caption:"Show on Files opens the tree; unticking the _Work folder takes the count from 31 to 29 files, and ticking it again brings them back"}),e[1]||(e[1]=t('<h3 id="advanced-the-patterns" tabindex="-1">Advanced: the patterns <a class="header-anchor" href="#advanced-the-patterns" aria-label="Permalink to &quot;Advanced: the patterns&quot;">​</a></h3><p>Under <strong>Advanced: the patterns</strong>, folded at first, the ticks are shown as the patterns they make. You can type them yourself, one per line:</p><table tabindex="0"><thead><tr><th>Field</th><th>Example</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Files to read, one pattern per line</strong></td><td><code>**/*.md</code> reads every note.</td><td>Which files of the folder belong to the story.</td></tr><tr><td><strong>Files to leave out, one pattern per line</strong></td><td><code>_Work/**</code></td><td>Which of those to leave out. To leave out the sample&#39;s <code>_Work/</code> notes, for instance, add <code>_Work/**</code>.</td></tr></tbody></table><p><code>*</code> matches any name, <code>**</code> any number of folders. The box is written when you leave it.</p><h3 id="leathercase-s-files" tabindex="-1">Leathercase&#39;s files <a class="header-anchor" href="#leathercase-s-files" aria-label="Permalink to &quot;Leathercase&#39;s files&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Leathercase&#39;s files go in</strong></td><td>&quot;Where Leathercase writes its own files for this story.&quot; Empty means the <code>suite</code> folder inside the story&#39;s folder (<code>The Lamp at Ferrol/suite</code>). Type another folder, or click <strong>Choose…</strong> to pick one.</td></tr></tbody></table><p>Under it, Leathercase&#39;s author data files for the story, each with a filled tick when it exists and, when it does not yet, when it is made:</p><table tabindex="0"><thead><tr><th>File</th><th>Made</th></tr></thead><tbody><tr><td><code>StoryThreads.md</code></td><td>made on your first thread</td></tr><tr><td><code>PlotGrid.md</code></td><td>made the first time the story is read</td></tr><tr><td><code>Accents.md</code></td><td>yours to tell: how each character speaks</td></tr><tr><td><code>Relationships.md</code></td><td>lines drawn on the old story map, read by the Graph</td></tr><tr><td><code>Comments.md</code></td><td>made on your first comment</td></tr><tr><td><code>WordLists.md</code></td><td>yours to write: a heading per category, the words under it</td></tr></tbody></table><p>What each holds is on <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>&quot;What the desk counts toward. With no target, the story is read and mapped, not counted down.&quot;</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Target</strong></td><td>&quot;The words the finished story should have.&quot; 0 for none.</td></tr><tr><td><strong>Deadline</strong></td><td>&quot;The day it should be done, if there is one.&quot; A date picker; clear it for no deadline.</td></tr><tr><td><strong>A day</strong></td><td>&quot;Words a writing day aims for; new stories start at 500.&quot; The starting figure comes from <strong>Settings › New stories</strong>.</td></tr><tr><td><strong>Days you write</strong></td><td>A button for each day of the week. &quot;every day counts; click to keep only some.&quot; Turn days off and the pace and the words a day needed by the deadline count only the days left on. Turning all seven back on means every day.</td></tr></tbody></table><p>Under the fields, a dashed box reads the goal back as one sentence, the way the Desk will count it. For example:</p><ul><li>&quot;60,000 words by 2026-12-31 is 640 a day from today, more than the 500 a day set. At the recent pace, done by 2027-03-14.&quot;</li><li>&quot;500 a day, 5 days a week, reaches 60,000 in 110 sittings, around 2027-03-20.&quot;</li><li>&quot;No target. 500 a day is the goal the desk counts against.&quot;</li><li>&quot;No target and no daily goal: the story is read and mapped, not counted down.&quot;</li><li>&quot;60,000 words: already there.&quot;</li><li>&quot;60,000 words by 2026-09-30: the deadline has passed, 12,000 to go.&quot;</li></ul><p>The last part, <strong>At the recent pace, done by …</strong>, appears once Leathercase has seen enough of your writing to project a finishing day. See <a href="/guide/guide/desk">The Desk</a>.</p><p><img src="'+i+'" alt="The Goal section with Target 60000, a deadline of 31 December 2026, A day 500, the weekday buttons, and the goal read back as a sentence" width="875" height="596" loading="lazy"></p><h2 id="prose" tabindex="-1">Prose <a class="header-anchor" href="#prose" aria-label="Permalink to &quot;Prose&quot;">​</a></h2><p>&quot;How the story is written, so the lenses read it right. Leathercase tells it from the page; confirm it or correct it.&quot;</p><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><p><strong>Language</strong> sets the story&#39;s language: &quot;The book&#39;s words and the templates follow the story&#39;s language, not the app&#39;s.&quot; The first choice, <strong>Told from the prose: English</strong> (or <strong>Told from the prose (English until there is enough)</strong>), lets Leathercase tell it from your paragraphs. The others are <strong>English (United States)</strong>, <strong>English (United Kingdom)</strong>, <strong>English (Canada)</strong>, <strong>Português (Brasil)</strong> and <strong>Português (Portugal)</strong>.</p><p>It changes:</p><ul><li>The words an export adds: Chapter One, Contents, by, END (see <a href="/guide/guide/export#the-book-s-own-words">Export</a>).</li><li>The language of the templates Leathercase offers for the story, such as the beat board&#39;s.</li><li>The heading of the sentence log as an agent reads it.</li></ul><p>It never changes the app&#39;s own language, which is set in <strong>Settings › Appearance</strong>. See <a href="/guide/reference/languages">Languages</a>.</p><h3 id="speech-is-written-as" tabindex="-1">Speech is written as <a class="header-anchor" href="#speech-is-written-as" aria-label="Permalink to &quot;Speech is written as&quot;">​</a></h3><p>How your story marks speech, so the dialogue and accents lenses find it. Each choice shows a sample line:</p><table tabindex="0"><thead><tr><th>Choice</th><th>Sample</th></tr></thead><tbody><tr><td><strong>As the prose reads</strong></td><td>Leathercase tells from the page</td></tr><tr><td><strong>Double quotes</strong></td><td>“Not tonight,” she said.</td></tr><tr><td><strong>Single quotes</strong></td><td>‘Not tonight,’ she said.</td></tr><tr><td><strong>A dash</strong></td><td>— Not tonight, she said.</td></tr><tr><td><strong>No speech marks</strong></td><td>She said it was not tonight.</td></tr></tbody></table><p>Leathercase reads your paragraphs and says what it found on the first row, such as <strong>double quotes, in 112 paragraphs</strong> (or <strong>nothing read that way yet</strong>). The convention it found is marked with its count and shows one of your own sentences; every other row shows that same sentence re-marked in its convention, so you see your own line each way. Hover a sample for &quot;your own sentence&quot; or &quot;your sentence, re-marked&quot;.</p><h3 id="thoughts-are-written-as" tabindex="-1">Thoughts are written as <a class="header-anchor" href="#thoughts-are-written-as" aria-label="Permalink to &quot;Thoughts are written as&quot;">​</a></h3><p>The same, for thought:</p><table tabindex="0"><thead><tr><th>Choice</th><th>Sample</th></tr></thead><tbody><tr><td><strong>As the prose reads</strong></td><td>Leathercase tells from the page</td></tr><tr><td><strong>An italic paragraph</strong></td><td><em>He is up there. He has to be.</em></td></tr><tr><td><strong>Italics anywhere</strong></td><td>She looked up. <em>He is up there.</em> She waited.</td></tr><tr><td><strong>Single quotes</strong></td><td>‘He is up there,’ she thought.</td></tr><tr><td><strong>Not marked</strong></td><td>He was up there, she knew.</td></tr></tbody></table><p>The Lamp at Ferrol declares double quotes for speech and an italic paragraph for thought. How the lens reads each is on <a href="/guide/guide/lenses#speech-and-thought-conventions">Lenses and style checks</a>.</p><h3 id="speakers" tabindex="-1">Speakers <a class="header-anchor" href="#speakers" aria-label="Permalink to &quot;Speakers&quot;">​</a></h3><p><strong>Speakers, in the order the lens tries them</strong> narrows and orders the cast the dialogue lens gives lines to. Each speaker is a chip with its number, <code>←</code> and <code>→</code> to move it earlier or later (<strong>Move Nora Vidal earlier</strong>), and <code>×</code> to remove it. Add one with <strong>+ from the cast</strong>, which lists your characters not yet in, or type a name in <strong>+ a name, then Enter</strong>. A name with no character note can be added too.</p><p>A speaker may carry a colour of its own after the name, <code>Nora Vidal #1f5f7a</code>. The accents lens marks that character&#39;s words in it; the dialogue lens does not colour lines by speaker, it tints speech and thought and names the speaker in the side column (see <a href="/guide/guide/lenses#dialogue">Lenses and style checks</a>). Left empty, every character note is a speaker, in cast order.</p><p><img src="'+l+'" alt="The Prose section: Language, the speech conventions with the detected one marked, and the Speakers chips of The Lamp at Ferrol" width="762" height="1100" loading="lazy"></p><h2 id="words" tabindex="-1">Words <a class="header-anchor" href="#words" aria-label="Permalink to &quot;Words&quot;">​</a></h2><p>&quot;The words to watch. Each change is written at once to Leathercase&#39;s file beside the story.&quot; This section edits the story&#39;s word lists in <code>WordLists.md</code>: each list as a row of chips, <code>×</code> to take a word out, and <strong>List</strong>, <strong>Word or phrase</strong> and <strong>Add</strong> to put one in. The words lens marks them on the manuscript page. Full details are on <a href="/guide/guide/comments#word-lists">Comments and word lists</a>.</p><p>How each character speaks (the words they use and never say) is not here: it is kept on each character&#39;s <strong>Voice</strong> tab in the <a href="/guide/guide/characters">characters</a> view.</p><h2 id="characters" tabindex="-1">Characters <a class="header-anchor" href="#characters" aria-label="Permalink to &quot;Characters&quot;">​</a></h2><p>&quot;The sections Leathercase adds, empty, to a character&#39;s note in Leathercase when you ask. Kept for every story of the home.&quot;</p><p><strong>Character sections</strong> is a box with one section name per line (&quot;one per line, for every story of the home&quot;), and <strong>Save the sections</strong>. They are kept in <code>suite/CharacterSections.md</code> at the home&#39;s root, so every story of the home shares them. See <a href="/guide/guide/characters">Characters</a>.</p><h2 id="graph" tabindex="-1">Graph <a class="header-anchor" href="#graph" aria-label="Permalink to &quot;Graph&quot;">​</a></h2><p>&quot;Names the Graph found that are not people. They stay in your prose and leave the Graph.&quot;</p><p><strong>Not people: names the Graph must not take</strong> lists the capitalised words the <a href="/guide/guide/graph">Graph</a> must not take for names, such as a month or a word of address. The Lamp at Ferrol has <code>Michaelmas</code> and <code>Pai</code>.</p><ul><li>Each is a chip with <code>×</code> to give it back to the Graph.</li><li>Below, dashed chips offer names found in the prose with no note of their own, with how often they appear (<code>Michaelmas 4×</code>). Click one to ignore it (&quot;found in the prose with no note; click to ignore&quot;).</li><li>Type any other name in <strong>a name, then Enter</strong>.</li></ul><p>The names stay in your prose; they only leave the Graph, the cast and the lists built from it. The same list can be undone from the Graph&#39;s <strong>Names you settled</strong>.</p><h2 id="plot-grid" tabindex="-1">Plot grid <a class="header-anchor" href="#plot-grid" aria-label="Permalink to &quot;Plot grid&quot;">​</a></h2><p>&quot;Which headings of StoryThreads.md do which job on the plot grid.&quot;</p><p>Under <strong>The grid&#39;s jobs, from StoryThreads.md</strong>, four lists, each offering the headings of your threads file, or <strong>none</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>What the chosen heading becomes</th></tr></thead><tbody><tr><td><strong>POV column</strong></td><td>The grid&#39;s point-of-view column, read as whose scene it is.</td></tr><tr><td><strong>Time column</strong></td><td>The grid&#39;s time column, read as when the scene happens.</td></tr><tr><td><strong>Main theme</strong></td><td>The thread the grid treats as the story&#39;s main theme.</td></tr><tr><td><strong>Plot points</strong></td><td>The thread the grid treats as the story&#39;s plot points.</td></tr></tbody></table><p>The Lamp at Ferrol sets <strong>POV</strong>, <strong>Time</strong> and <strong>Theme: What do we owe the drowned?</strong>. A heading chosen here that is no longer in the file shows in the warning colour as <strong>POV (not in StoryThreads.md)</strong>. With no heading in the file yet the section says: &quot;No heading yet: the grid&#39;s column menu sets these when the threads file has some.&quot; The grid&#39;s own column menu sets the same four; see <a href="/guide/guide/plot-grid">Plot grid</a>.</p><h2 id="what-is-not-on-this-page" tabindex="-1">What is not on this page <a class="header-anchor" href="#what-is-not-on-this-page" aria-label="Permalink to &quot;What is not on this page&quot;">​</a></h2><p>Some of a story&#39;s settings are kept in <code>Story.json</code> but set elsewhere, where they make sense:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Where</th></tr></thead><tbody><tr><td>The app the story opens in</td><td><strong>Settings › Sources</strong>, or the chooser on the manuscript page</td></tr><tr><td>The pen name it is published under</td><td><strong>Settings › Export</strong> for the story (its <strong>Byline</strong> row)</td></tr><tr><td>Other names and pronouns confirmed for a character</td><td>The Graph</td></tr><tr><td>The grid&#39;s column order</td><td>The plot grid</td></tr><tr><td>The story&#39;s own kinds</td><td><a href="/guide/guide/declare-a-story">Declaring a story</a></td></tr></tbody></table><p>A story declared from a project note reads that note&#39;s keys once, when it is declared: The Lamp at Ferrol&#39;s <code>writing-target</code>, <code>writing-daily</code>, <code>writing-deadline</code>, <code>dialogue</code>, <code>thoughts</code>, <code>speakers</code>, <code>plot-pov</code>, <code>plot-time</code>, <code>plot-theme</code> and <code>story-ignore</code> filled these fields. After that, the settings page is where they change. See <a href="/guide/reference/front-matter">Front matter</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/declare-a-story">Declaring a story</a></li><li><a href="/guide/guide/how-a-story-is-read">How a story is read</a></li><li><a href="/guide/guide/lenses">Lenses and style checks</a></li><li><a href="/guide/guide/desk">The Desk</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/guide/characters">Characters</a></li><li><a href="/guide/guide/graph">Graph</a></li><li><a href="/guide/guide/plot-grid">Plot grid</a></li><li><a href="/guide/reference/front-matter">Front matter</a></li></ul>',57))])}const k=r(g,[["render",c]]);export{b as __pageData,k as default};
